const request = $input.first().json;
const body = request.body ?? request;
const command = body.command ?? body;
const security = command.security_context ?? body.security_context ?? {};
const message = typeof command.message === 'string' ? command.message.trim() : '';
const intent = typeof command.intent === 'string' && command.intent.trim()
  ? command.intent.trim()
  : 'conversation';
const representativeId = typeof security.representant_id === 'string'
  ? security.representant_id.trim()
  : (typeof body.representant_id === 'string' ? body.representant_id.trim() : '');
const requestId = typeof command.request_id === 'string' ? command.request_id : null;

if (command.schema_version && command.schema_version !== '1.0') {
  throw new Error('La version du contrat agent n’est pas prise en charge.');
}

if (!message) {
  throw new Error('Le champ message est requis.');
}

if (message.length > 1000) {
  throw new Error('Le message dépasse la limite de 1000 caractères.');
}

if (!['conversation', 'clients_recents'].includes(intent)) {
  throw new Error('L’intention demandée n’est pas autorisée.');
}

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(representativeId)) {
  throw new Error('Le contexte représentant est invalide.');
}

return [{
  json: {
    chatInput: message,
    intent,
    representativeId,
    requestId,
    sessionId: typeof command.session_id === 'string'
      ? command.session_id.slice(0, 100)
      : null
  }
}];

const raw = $input.first().json.resultat;
const resultat = typeof raw === 'string' ? JSON.parse(raw) : raw;
const clients = Array.isArray(resultat?.clients) ? resultat.clients : [];

const lignes = clients.map((client, index) =>
  `${index + 1}. ${client.nom_client} — ${client.code_client} — ${client.statut_dossier}`
);

return [{
  json: {
    output: clients.length
      ? `Voici les ${clients.length} clients les plus récents :\n\n${lignes.join('\n')}`
      : 'Aucun client récent n’est disponible.',
    sessionId: $('Webhook - Clients récents').item.json.body?.session_id ?? null
  }
}];

const request = $input.first().json;
const body = request.body ?? request;
const reference = typeof body.client_reference === 'string'
  ? body.client_reference.trim()
  : '';
const representativeId = typeof body.representant_id === 'string'
  ? body.representant_id.trim()
  : '';

if (!reference) {
  throw new Error('Le champ client_reference est requis.');
}

if (reference.length > 120) {
  throw new Error('La référence client dépasse la limite de 120 caractères.');
}

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(representativeId)) {
  throw new Error('Le contexte représentant est invalide.');
}

return [{ json: { clientReference: reference, representativeId } }];

const raw = $input.first().json.resultat;
const resultat = typeof raw === 'string' ? JSON.parse(raw) : raw;
const clients = Array.isArray(resultat?.clients) ? resultat.clients : [];

const lignes = clients.map((client, index) => {
  const documents = Array.isArray(client.documents_manquants)
    ? client.documents_manquants.map((document) => `   • ${document.document}`).join('\n')
    : '';
  const titre = `${index + 1}. ${client.nom_client} — ${client.code_client} — ${client.nombre_documents_manquants} document(s) manquant(s)`;
  return documents ? `${titre}\n${documents}` : titre;
});

return [{
  json: {
    output: clients.length
      ? `${clients.length} client(s) ont des documents manquants :\n\n${lignes.join('\n\n')}`
      : 'Aucun client n’a de document manquant.',
    requestId: $('Webhook - Documents manquants').item.json.body?.request_id ?? null,
    sessionId: $('Webhook - Documents manquants').item.json.body?.session_id ?? null
  }
}];

