WITH contexte AS MATERIALIZED (
  SELECT set_config('app.role', 'representant', true), set_config('app.representant_id', $1::uuid::text, true)
)
SELECT crm.consulter_portefeuille($2::jsonb, $3::jsonb, $4::integer, ARRAY(SELECT jsonb_array_elements_text($5::jsonb)), NULLIF($6, 'null')::jsonb) AS resultat FROM contexte;

parameters.jsCode:
const raw = $input.first().json.resultat;
const resultat = typeof raw === 'string' ? JSON.parse(raw) : raw;
const rows = Array.isArray(resultat?.rows) ? resultat.rows : [];
const request = $('Webhook - Portefeuille').item.json.body ?? {};
const format = request.command?.parameters?.format ?? 'text';
const aggregate = request.command?.parameters?.aggregate ?? null;
const money = (value) => value == null ? 'Non renseigné' : new Intl.NumberFormat('fr-CA', { style: 'currency', currency: 'CAD', maximumFractionDigits: 0 }).format(Number(value));
let output;
if (!rows.length) output = 'Aucun dossier client ne correspond à ces critères.';
else if (aggregate?.operation === 'max' && aggregate?.field === 'revenu_annuel') { const row = rows[0]; output = `Le revenu annuel le plus élevé est celui de ${row.nom_client} — ${row.code_client} : ${money(row.revenu_annuel)}.`; }
else if (format === 'table') { const header = '| Client | Code client | Statut | Priorité |\n|---|---|---|---:|'; const lines = rows.map((row) => `| ${row.nom_client} | ${row.code_client} | ${row.statut_dossier} | ${row.priority_score} |`); output = `${header}\n${lines.join('\n')}`; }
else { const lines = rows.map((row, index) => { const reasons = Array.isArray(row.priority_reasons) && row.priority_reasons.length ? ` — ${row.priority_reasons.join(', ')}` : ''; return `${index + 1}. ${row.nom_client} — ${row.code_client} — ${row.statut_dossier} — priorité ${row.priority_score}${reasons}`; }); output = `${rows.length} dossier(s) trouvé(s) :\n\n${lines.join('\n')}`; }
return [{ json: { output, resultat, requestId: request.request_id ?? null, sessionId: request.session_id ?? null } }];

